async function collectEditResult(api, sessionId, prompt, vaultPath) {
  let text = "";
  for await (const chunk of api.sendMessage(sessionId, prompt, vaultPath)) {
    if (chunk.type === "text")
      text += chunk.content;
    if (chunk.type === "error")
      throw new Error(chunk.content);
  }
  return text.trim();
}
